mapper.select:
SELECT il.id, il.product_id, p.name AS product_name, il.change_type AS changeType, CASE il.change_type WHEN 'PURCHASE' THEN '进货入库' WHEN 'SALE' THEN '销售出库' WHEN 'ADJUST' THEN '库存盘点' WHEN 'DAMAGE' THEN '报损' WHEN 'RETURN' THEN '退货入库' ELSE il.change_type END AS change_type_text, il.change_quantity AS changeQuantity, il.before_stock AS beforeStock, il.after_stock AS afterStock, il.related_order_no AS relatedOrderNo, il.operator_id AS operatorId, u.real_name AS operator_name, il.remark, il.create_time AS createTime FROM inventory_log il LEFT JOIN product p ON il.product_id = p.id LEFT JOIN sys_user u ON il.operator_id = u.id
AND il.product_id = #{productId}
AND il.change_type = #{changeType}
AND il.create_time >= #{startDate}
AND il.create_time < DATE_ADD(#{endDate}, INTERVAL 1 DAY)
ORDER BY il.create_time DESC LIMIT #{offset}, #{pageSize}

SELECT COUNT(*)
FROM inventory_log il


        AND il.product_id = #{productId}


        AND il.change_type = #{changeType}


        AND il.create_time >= #{startDate}


        AND il.create_time < DATE_ADD(#{endDate}, INTERVAL 1 DAY)
